package com.jmadsen.dashhop;
import android.app.KeyguardManager;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;
/** Own native overlays only; never embeds or forwards input to third-party apps. */
final class UtilityPopupManager {
 static String kind="";static Context c;static WindowManager wm;static LinearLayout root;static FrameLayout body;static WindowManager.LayoutParams params;static Runnable back;static final Handler h=new Handler(Looper.getMainLooper());static boolean receiverRegistered;static Runnable cleanup;
 static boolean showing(){return root!=null;}
 static final Runnable health=new Runnable(){public void run(){if(root==null)return;if(!Settings.canDrawOverlays(c)||!c.getSystemService(PowerManager.class).isInteractive()||c.getSystemService(KeyguardManager.class).isKeyguardLocked()){interrupt();return;}h.postDelayed(this,1000);}};
 static final BroadcastReceiver screen=new BroadcastReceiver(){public void onReceive(Context c,Intent i){interrupt();}};
 static void dismiss(){dismiss("requested");}
 static void dismiss(String reason){if(root!=null){java.util.Map<String,Object> fields=new java.util.LinkedHashMap<>();fields.put("popup_kind",kind);fields.put("popup_close_reason",reason);Diagnostics.operation("utility_popup_dismiss_requested",fields);}h.removeCallbacks(health);saveBounds();Runnable close=cleanup;cleanup=null;if(close!=null)close.run();if(root!=null){try{wm.removeViewImmediate(root);}catch(Exception ignored){}root=null;Diagnostics.info("utility_popup_closed_"+kind);}if(receiverRegistered){try{c.unregisterReceiver(screen);}catch(Exception ignored){}receiverRegistered=false;}kind="";body=null;back=null;}
 static void toggle(Context context,String type){if(showing()&&kind.equals(type))dismiss();else open(context,type);}
 static void saveBounds(){if(root==null||params==null||c==null)return;android.util.DisplayMetrics d=new android.util.DisplayMetrics();wm.getDefaultDisplay().getMetrics(d);android.content.SharedPreferences.Editor e=new ShortcutRepository(c).prefs.edit();String key="popup."+kind+".";e.putFloat(key+"x",params.x/(float)Math.max(1,d.widthPixels)).putFloat(key+"y",params.y/(float)Math.max(1,d.heightPixels)).putFloat(key+"w",params.width/(float)Math.max(1,d.widthPixels)).putFloat(key+"h",params.height/(float)Math.max(1,d.heightPixels)).apply();}
 static void restoreBounds(){android.util.DisplayMetrics d=new android.util.DisplayMetrics();wm.getDefaultDisplay().getMetrics(d);android.content.SharedPreferences p=new ShortcutRepository(c).prefs;String key="popup."+kind+".";if(p.contains(key+"w")){params.x=Math.round(p.getFloat(key+"x",0)*d.widthPixels);params.y=Math.round(p.getFloat(key+"y",0)*d.heightPixels);params.width=Math.round(p.getFloat(key+"w",.5f)*d.widthPixels);params.height=Math.round(p.getFloat(key+"h",.7f)*d.heightPixels);}clamp();}
 static void open(Context context,String type){dismiss("replaced_by_"+type);c=context.getApplicationContext();if(!Settings.canDrawOverlays(c)){Toast.makeText(c,"Allow display over other apps in DashHopper Settings to open utility popups",Toast.LENGTH_LONG).show();return;}try{wm=c.getSystemService(WindowManager.class);kind=type;root=new LinearLayout(c);root.setOrientation(1);GradientDrawable bg=new GradientDrawable();bg.setColor(type.equals("calendar")?0xff173d59:0xff14384b);bg.setCornerRadius(px(16));bg.setStroke(px(2),0xff56d9d0);root.setBackground(bg);root.setPadding(px(6),px(6),px(6),px(6));root.setFocusableInTouchMode(true);root.setOnKeyListener((v,key,event)->{if(key==android.view.KeyEvent.KEYCODE_BACK&&event.getAction()==android.view.KeyEvent.ACTION_UP){goBack();return true;}return false;});
 android.util.DisplayMetrics d=new android.util.DisplayMetrics();wm.getDefaultDisplay().getMetrics(d);int width=Math.min(d.widthPixels-px(16),px(640)),height=Math.min(d.heightPixels-px(16),px(560));params=new WindowManager.LayoutParams(width,height,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);params.gravity=Gravity.TOP|Gravity.LEFT;params.x=Math.max(0,(d.widthPixels-width)/2);params.y=Math.max(0,(d.heightPixels-height)/2);params.softInputMode=WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE;if(type.equals("audio")){params.width=Math.min(d.widthPixels,px(520));params.height=Math.min(d.heightPixels,px(380));}restoreBounds();
 LinearLayout titlebar=new LinearLayout(c);TextView backControl=button("‹",UtilityPopupManager::goBack),title=label(type.equals("calendar")?"Calendar":type.equals("audio")?"Audio Mini":type.equals("notes")?"Notepad Mini":"Weather",21),close=button("×",()->dismiss("close_button"));titlebar.addView(backControl,new LinearLayout.LayoutParams(px(48),px(48)));titlebar.addView(title,new LinearLayout.LayoutParams(0,px(48),1));titlebar.addView(close,new LinearLayout.LayoutParams(px(48),px(48)));root.addView(titlebar);float[] drag=new float[4];title.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN){drag[0]=e.getRawX();drag[1]=e.getRawY();drag[2]=params.x;drag[3]=params.y;return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL)saveBounds();if(e.getActionMasked()==MotionEvent.ACTION_MOVE){params.x=(int)(drag[2]+e.getRawX()-drag[0]);params.y=(int)(drag[3]+e.getRawY()-drag[1]);clamp();update();return true;}return true;});body=new FrameLayout(c);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));TextView resize=label("↘ Drag to resize",13);resize.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);root.addView(resize,new LinearLayout.LayoutParams(-1,px(48)));resize.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN){drag[0]=e.getRawX();drag[1]=e.getRawY();drag[2]=params.width;drag[3]=params.height;return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL)saveBounds();if(e.getActionMasked()==MotionEvent.ACTION_MOVE){params.width=(int)(drag[2]+e.getRawX()-drag[0]);params.height=(int)(drag[3]+e.getRawY()-drag[1]);clamp();update();return true;}return true;});
 if(type.equals("calendar")){CalendarUtility view=new CalendarUtility(c);body.addView(view,new FrameLayout.LayoutParams(-1,-1));back=view::back;}else if(type.equals("audio")){AudioPanel view=new AudioPanel(c);body.addView(view,new FrameLayout.LayoutParams(-1,-1));back=UtilityPopupManager::dismiss;}else if(type.equals("notes")){NotepadPanel view=new NotepadPanel(c);cleanup=view::close;body.addView(view,new FrameLayout.LayoutParams(-1,-1));back=UtilityPopupManager::dismiss;}else{WeatherPanel view=new WeatherPanel(c,new ShortcutRepository(c));view.mode="compact";view.render();body.addView(view,new FrameLayout.LayoutParams(-1,-1));back=()->{if(!view.mode.equals("compact"))view.view("compact");else dismiss();};}wm.addView(root,params);root.requestFocus();c.registerReceiver(screen,new IntentFilter(Intent.ACTION_SCREEN_OFF));receiverRegistered=true;h.post(health);Diagnostics.info("utility_popup_opened_"+type);
 }catch(Exception e){Diagnostics.error("utility_popup_failed",e);dismiss();Toast.makeText(c,"Unable to open popup; use DashHopper Settings to recover",Toast.LENGTH_LONG).show();}}
 static void interrupt(){if(c!=null)AudioFocusCoordinator.get(c).end(false);dismiss("system_screen_permission_or_service_interruption");}
 static void goBack(){if(back!=null)back.run();else dismiss();}
 static void content(View view){if(body!=null){body.removeAllViews();body.addView(view,new FrameLayout.LayoutParams(-1,-1));}}
 static void update(){try{if(root!=null)wm.updateViewLayout(root,params);}catch(Exception e){Diagnostics.error("utility_popup_update_failed",e);dismiss("window_update_failure");}}
 static void clamp(){android.util.DisplayMetrics d=new android.util.DisplayMetrics();wm.getDefaultDisplay().getMetrics(d);int[] b=PopupBoundsPolicy.fit(params.x,params.y,params.width,params.height,d.widthPixels,d.heightPixels,px(340),px(260));params.x=b[0];params.y=b[1];params.width=b[2];params.height=b[3];}
 static int px(int n){return DockController.px(c,n);}static TextView label(String s,int size){TextView t=new TextView(c);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(size);t.setGravity(Gravity.CENTER);return t;}static TextView button(String s,Runnable action){TextView t=label(s,24);t.setContentDescription(s.equals("×")?"Close utility popup":"Back");t.setOnClickListener(v->action.run());return t;}
}
